<template>
  <div />
</template>
<script lang="ts" setup>
definePageMeta({
  auth: false,
  middleware: [
    function () {
      const { isAuthenticated } = useUserRole();
      if (isAuthenticated.value) {
        return navigateTo({ name: 'projects' }, { replace: true });
      } else {
        return navigateTo({ name: 'login' }, { replace: true });
      }
    },
  ],
});
</script>
